#include "test_platform.hpp"
#include "edudb.hpp"
#include "fencing.hpp"
#include "aries_logical.hpp"
#include <chrono>
#include <algorithm>
#include <cstdlib>
#include <filesystem>
#include <iostream>
#include <map>
using namespace edudb;namespace fs=std::filesystem;
namespace {
void check(bool b,const std::string& why){if(!b)throw std::runtime_error(why);}
template<class F>void error(const std::string& wanted,F f){try{f();}catch(const DbError& e){check(e.code==wanted,"wanted "+wanted+", got "+e.code+": "+e.what());return;}throw std::runtime_error("missing "+wanted);}
json sql(Engine& db,const std::string& s,const std::string& text){auto j=db.execute(s,text);check(j.value("ok",false),text+": "+j.dump());return j;}
json denied(Engine& db,const std::string& s,const std::string& text,const std::string& code){auto j=db.execute(s,text);check(!j.value("ok",true)&&j["error"]["code"]==code,text+": wanted "+code+", actual "+j.dump());return j;}
StorageOptions opts(const fs::path& root){StorageOptions o;o.recovery_mode="ARIES_LOGICAL";o.fencing_directory=(root/"fence").u8string();return o;}
json expected(){return json::array({json::array({1,"original-one"}),json::array({2,"committed-two"})});}
json rows(Engine& db,const std::string& s){return sql(db,s,"SELECT id,v FROM t ORDER BY id")["rows"];}
std::map<int,StoredRow> stored(Storage& db,const std::shared_ptr<Transaction>& tx){std::map<int,StoredRow> result;auto cursor=db.scan(tx,"t");StoredRow row;while(cursor->next(row))result.emplace(row.values[0].get<int>(),row);return result;}
void seed(const fs::path& root){
 {Engine db((root/"db").u8string(),2,32u*1024u*1024u,opts(root));auto s=db.open_session();sql(db,s,"CREATE TABLE t(id INTEGER PRIMARY KEY,v VARCHAR(80))");sql(db,s,"INSERT INTO t VALUES(1,'original-one'),(2,'original-two')");db.checkpoint();}
 {Storage db((root/"db").u8string(),2,32u*1024u*1024u,opts(root));auto tx=db.begin();auto records=stored(db,tx);check(records.size()==2&&records.at(1).id.page_id==records.at(2).id.page_id,"fixture rows must actually share a physical heap page");db.rollback(tx);}
}
json takeover(const fs::path& root,const json& identity){recovery::FenceDomain domain(identity.at("uuid").get<std::string>(),(root/"fence").u8string());auto permit=domain.promote(std::string(32,'b'),identity.at("timeline").get<std::string>(),identity.at("durable_lsn").get<std::uint64_t>());return permit.state();}
void verified(Engine& db,const std::string& s){check(sql(db,s,"VERIFY")["verification"]["ok"],"VERIFY after real inverse failed");}
json units(const fs::path& root){json passed=json::array();
 {auto p=root/"engine-fenced-commit";seed(p);Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto a=db.open_session(),b=db.open_session();sql(db,a,"BEGIN");sql(db,a,"UPDATE t SET v='pending-one' WHERE id=1");sql(db,b,"UPDATE t SET v='committed-two' WHERE id=2");auto promoted=takeover(p,db.recovery_identity());auto refused=denied(db,a,"COMMIT","FENCED");sql(db,a,"ROLLBACK");check(rows(db,b)==expected(),"fenced outer user rollback destroyed another key's committed mini-transaction");verified(db,b);check(!db.diagnostics()["storage"]["recovery_required"].get<bool>(),"ordinary fencing plus successful local compensation poisoned database");check(!db.recovery_identity().value("writable",true),"old owner still reports writable");passed.push_back({{"case","actual_Engine_fenced_outer_COMMIT_then_inverse_preserves_same_page_other_key_commit"},{"status","PASS"},{"promotion",promoted},{"commit_response",refused}});}
 {auto p=root/"future-and-zero";seed(p);Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto s=db.open_session();takeover(p,db.recovery_identity());json refused=json::array();for(const std::string text:{"INSERT INTO t VALUES(3,'future')","UPDATE t SET v='future' WHERE id=1","DELETE FROM t WHERE id=999","UPDATE t SET v='future' WHERE id=999"})refused.push_back(denied(db,s,text,"FENCED"));check(rows(db,s)==json::array({json::array({1,"original-one"}),json::array({2,"original-two"})}),"fenced new/zero-row SQL changed state");check(!db.diagnostics()["storage"]["recovery_required"].get<bool>(),"ownership loss itself must not globally fail-stop local reads");passed.push_back({{"case","future_and_zero_row_SQL_write_intents_rejected_after_takeover"},{"status","PASS"},{"responses",refused}});}
 {auto p=root/"readonly";seed(p);Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto s=db.open_session();sql(db,s,"SET TRANSACTION READ ONLY");denied(db,s,"UPDATE t SET v='forbidden' WHERE id=1","READ_ONLY_TRANSACTION");sql(db,s,"BEGIN");sql(db,s,"SAVEPOINT held");denied(db,s,"ROLLBACK TO absent","SAVEPOINT_NOT_FOUND");sql(db,s,"ROLLBACK");check(rows(db,s).size()==2&&!db.diagnostics()["storage"]["recovery_required"].get<bool>(),"read-only/error unwinding leaked or poisoned logical state");verified(db,s);passed.push_back({{"case","read_only_write_rejection_and_recoverable_statement_exception"},{"status","PASS"}});}
 {auto p=root/"direct-storage";seed(p);Storage db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto a=db.begin(),b=db.begin();auto records=stored(db,a);db.update_row(a,"t",records.at(1).id,json::array({1,"pending-one"}));db.update_row(b,"t",records.at(2).id,json::array({2,"committed-two"}));db.commit(b);takeover(p,db.recovery_identity());error("FENCED",[&]{db.commit(a);});db.rollback(a);auto reader=db.begin();auto after=stored(db,reader);check(after.at(1).values==expected()[0]&&after.at(2).values==expected()[1],"native Storage compensation after fencing lost same-page other-key commit");error("FENCED",[&]{db.insert_row(reader,"t",json::array({3,"denied-direct"}));});check(db.verify(reader)["ok"],"native Storage VERIFY after compensation");db.rollback(reader);check(!db.recovery_required(),"native fencing unwind failed closed despite successful undo");passed.push_back({{"case","direct_Storage_fenced_commit_real_rollback_and_new_write_guard"},{"status","PASS"}});}
 {auto p=root/"ddl-post-durable";seed(p);json response,diagnostic;check(edudb_test::set_env("EDUDB_TEST_IO_FAULT","aries_after_manager_commit_once")==0,"set controlled DDL fault");try{Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));check(edudb_test::set_env("EDUDB_TEST_IO_FAULT","")==0,"clear controlled fault");auto s=db.open_session();response=denied(db,s,"CREATE TABLE survived(id INTEGER PRIMARY KEY,v INTEGER)","IO_ERROR");diagnostic=db.diagnostics();check(diagnostic["storage"]["recovery_required"],"DDL post-durable exception did not force recovery-required");denied(db,s,"INSERT INTO t VALUES(3,'after-failure')","RECOVERY_REQUIRED");}catch(...){edudb_test::set_env("EDUDB_TEST_IO_FAULT","");throw;}
  {Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto s=db.open_session();check(sql(db,s,"SELECT COUNT(*) FROM survived")["rows"]==json::array({json::array({0})}),"physically committed DDL was undone after UNKNOWN response");verified(db,s);}passed.push_back({{"case","physical_DDL_post_Manager_COMMIT_exception_is_UNKNOWN_and_restart_keeps_DDL"},{"status","PASS"},{"response",response},{"diagnostic",diagnostic}});}
 {auto p=root/"mini-post-force";seed(p);{Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto s=db.open_session();sql(db,s,"UPDATE t SET v='committed-two' WHERE id=2");}json response;check(edudb_test::set_env("EDUDB_TEST_IO_FAULT","aries_after_commit_force_once")==0,"set mini force fault");try{Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));check(edudb_test::set_env("EDUDB_TEST_IO_FAULT","")==0,"clear mini force fault");auto s=db.open_session();response=denied(db,s,"UPDATE t SET v='no-outer-success' WHERE id=1","IO_ERROR");check(db.diagnostics()["storage"]["recovery_required"],"mini force uncertainty did not fail-stop");}catch(...){edudb_test::set_env("EDUDB_TEST_IO_FAULT","");throw;}
  for(int pass=0;pass<2;++pass){Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto s=db.open_session();check(rows(db,s)==expected(),"logical recovery after committed mini but no outer COMMIT lost another key or kept loser");verified(db,s);}passed.push_back({{"case","mini_post_force_exception_then_real_SQL_restart_inverses_outer_loser_preserving_prior_commit"},{"status","PASS"},{"response",response}});}
 {auto p=root/"native-destructor";seed(p);std::uint64_t abandoned=0;std::string uuid;
  {Storage db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto a=db.begin(),b=db.begin();abandoned=a->id;uuid=db.recovery_identity().at("uuid");auto records=stored(db,a);db.update_row(a,"t",records.at(1).id,json::array({1,"close-must-undo"}));db.update_row(b,"t",records.at(2).id,json::array({2,"committed-two"}));db.commit(b);}
  // Analysis only: no Storage/Manager recovery may manufacture this completion.
  {logical::Journal journal((p/"db").u8string(),uuid);auto losers=journal.loser_transactions();check(std::find(losers.begin(),losers.end(),abandoned)==losers.end(),"normal native Storage destructor left a logical loser pending for future startup");auto log=journal.wal_records();bool clr=false,ended=false;for(const auto& record:log["records"])if(record["tx"]==abandoned){if(record["type"]=="LOGICAL_CLR")clr=true;if(record["type"]=="LOGICAL_END")ended=true;}check(clr&&ended,"normal native destructor did not persist actual logical CLR and END before any startup recovery");}
  {Engine db((p/"db").u8string(),2,32u*1024u*1024u,opts(p));auto s=db.open_session();check(rows(db,s)==expected(),"normal native close erased another key's durable commit");verified(db,s);}passed.push_back({{"case","native_Storage_clean_destructor_performs_real_inverse_and_END_before_startup"},{"status","PASS"}});}
 return {{"status","PASS"},{"checks",passed},{"scope","Actual Engine SQL and sequential distinct-key native Storage composition through one final merged build; same-machine OS fencing and controlled post-force exceptions. Not physical power-loss or performance proof."}};
}
}
int main(int argc,char** argv){try{check(argc==1||argc==2,"usage [NEWROOT]");const auto root=argc==2?fs::u8path(argv[1]):fs::absolute(fs::path("logical-fence-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())));check(!fs::exists(root),"test root must be new");std::cout<<units(root).dump(2)<<'\n';return 0;}catch(const DbError& e){std::cerr<<json{{"status","ERROR"},{"code",e.code},{"message",e.what()}}.dump()<<'\n';return 4;}catch(const std::exception& e){std::cerr<<json{{"status","FAIL"},{"message",e.what()}}.dump()<<'\n';return 5;}}
